const FLOWER_DB = [
  // ── 1-10: Classic Beauties ──
  { id:1,  emoji:'🌹', title:'Rose',              latin:'Rosa',                     description:'Roses are the eternal symbol of love, offered in velvety crimson, blush pink, champagne, and pure white. Their intoxicating fragrance and thornlined stems have inspired poets for centuries. Prized for weddings, perfumery, and celebrations worldwide, climbing and shrub varieties fill gardens with layered blooms all summer long.',                                       tags:['romantic','fragrant','garden','gifting'], type:'Shrub',     keywords:['rose','love','romance','red','pink','fragrant','wedding','velvety','thorns','garden','perfume','classic','gift','valentine','bouquet'] },
  { id:2,  emoji:'🌷', title:'Tulip',             latin:'Tulipa',                   description:'Tulips burst from the ground each spring in a parade of scarlet, violet, yellow, striped and parrot varieties with ruffled edges. Originally from Central Asia and made famous by Dutch tulip mania, these bulb flowers symbolise perfect love and cheerfulness. Their cup-shaped blooms are icons of springtime and naturalise beautifully in meadows.',                          tags:['spring','bulb','colorful','Dutch'],       type:'Bulb',      keywords:['tulip','spring','bulb','Dutch','cup','yellow','purple','red','striped','cheerful','love','Holland','Netherlands','seasonal','easy'] },
  { id:3,  emoji:'🌸', title:'Cherry Blossom',    latin:'Prunus serrulata',         description:'Cherry blossoms, or sakura, are Japan\'s most treasured flower. Delicate pink and white blooms carpet the earth for just two glorious weeks each spring, their fleeting beauty symbolising the transience of life. Parks fill with hanami picnics beneath soft petal clouds, and the blossom appears on bare branches before the leaves to create a dreamlike canopy.',          tags:['Japanese','spring','fleeting','pink'],    type:'Tree',      keywords:['sakura','cherry','blossom','Japan','pink','delicate','spring','ephemeral','transience','hanami','picnic','tree','petals','soft','white'] },
  { id:4,  emoji:'🌻', title:'Sunflower',         latin:'Helianthus annuus',        description:'Sunflowers are cheerful giants, their golden heads tracking the sun in a behaviour called heliotropism. Native to the Americas, they produce edible oil-rich seeds and grow up to three metres tall. They radiate warmth and optimism in any garden or field. Van Gogh immortalised their brilliant yellow petals framing a dark, textured seed centre.',                      tags:['sunny','tall','edible','cheerful'],       type:'Annual',    keywords:['sunflower','yellow','sun','golden','tall','seeds','edible','heliotropism','happy','bright','summer','field','Van Gogh','warmth','giant'] },
  { id:5,  emoji:'💜', title:'Lavender',          latin:'Lavandula angustifolia',   description:'Lavender fills Provençal fields with hazy purple waves and a calming, sweet fragrance used for millennia in perfumery, medicine, and cooking. Its essential oil promotes relaxation and sleep, and it attracts bees and butterflies while repelling mosquitoes. Hardy and drought-tolerant, it thrives in sunny, well-drained soil.',                                             tags:['fragrant','calming','purple','herb'],     type:'Herb',      keywords:['lavender','purple','fragrant','calming','relaxing','aromatherapy','Provence','herb','essential oil','sleep','bees','butterflies','drought','perfume','soothing'] },
  { id:6,  emoji:'🌺', title:'Hibiscus',          latin:'Hibiscus rosa-sinensis',   description:'Hibiscus blooms are large trumpet-shaped flowers with prominent stamens, vibrant in red, pink, orange, and yellow. Common in tropical gardens and Hawaii\'s state flower, their dried petals brew a tart, Vitamin C-rich herbal tea. In many cultures they are worn in hair or used in traditional medicine and hair care.',                                                   tags:['tropical','vibrant','tea','Hawaii'],      type:'Shrub',     keywords:['hibiscus','tropical','red','pink','orange','Hawaii','tea','herbal','large','trumpet','bright','vitamin','summer','exotic','bold'] },
  { id:7,  emoji:'🪻', title:'Iris',              latin:'Iris germanica',           description:'Irises are architectural flowers with intricate falls and standards creating a dramatic sculptural effect. Named after the Greek goddess of the rainbow, they appear in every colour imaginable. Their rhizomes produce orris root, a precious perfumery fixative, and Claude Monet painted his Giverny iris garden obsessively in jewel-toned canvases.',                      tags:['architectural','colorful','artistic'],    type:'Perennial', keywords:['iris','purple','blue','architectural','rainbow','Monet','garden','rhizome','orris','perfume','artistic','elegant','sculptural','falls','standards'] },
  { id:8,  emoji:'🌼', title:'Daisy',             latin:'Bellis perennis',          description:'Daisies are the quintessential meadow flower — cheerful white petals radiating from a sunny yellow centre. She loves me, she loves me not is plucked worldwide from their petals. Incredibly hardy and low-maintenance, they naturalise in lawns and meadows, attracting pollinators all summer with simple, pure charm.',                                                      tags:['meadow','simple','cheerful','wildflower'], type:'Perennial', keywords:['daisy','white','yellow','meadow','wildflower','simple','cheerful','chain','petals','lawn','pollinator','rustic','cottage','field','innocent'] },
  { id:9,  emoji:'🌾', title:'Lily of the Valley',latin:'Convallaria majalis',      description:'Lily of the Valley produces tiny bell-shaped white flowers on arching stems with a breathtakingly fresh, sweet fragrance — one of perfumery\'s most coveted scents. Blooming briefly in spring, it symbolises purity and returning joy. A traditional bridal flower chosen by Princess Diana, it is entirely toxic despite its innocent appearance.',                         tags:['fragrant','bridal','spring','woodland'],  type:'Perennial', keywords:['lily of the valley','bells','white','fragrant','spring','bridal','wedding','woodland','toxic','sweet','shade','delicate','pure','Diana','perfume'] },
  { id:10, emoji:'🌿', title:'Peony',             latin:'Paeonia lactiflora',       description:'Peonies are beloved for their enormous ruffled blooms packed with layers of soft pink, blush, coral, magenta, and white petals. Their brief late-spring season makes each flowering feel precious. A top choice for romantic wedding bouquets, peonies live for decades and improve each year. They symbolise prosperity, good luck, and bashfulness.',                         tags:['romantic','ruffled','bridal','lush'],     type:'Perennial', keywords:['peony','pink','ruffled','romantic','wedding','bouquet','lush','layered','blush','coral','fragrant','spring','longevity','prosperity','bashful'] },

  // ── 11-20: Autumn & Exotic ──
  { id:11, emoji:'🏵️', title:'Chrysanthemum',    latin:'Chrysanthemum morifolium', description:'Chrysanthemums bloom in pompom, spider, cushion, and anemone forms in every colour from white to bronze. The official flower of autumn, they are celebrated at festivals across Japan, China, and Korea. In Japan a single petal is placed in sake glasses as an autumn tradition, and they are among the world\'s most popular cut flowers.',                               tags:['autumn','versatile','Asian','long-lasting'], type:'Perennial', keywords:['chrysanthemum','mum','autumn','fall','Japanese','Chinese','pompom','bronze','orange','white','festival','longevity','celebration','seasonal','imperial'] },
  { id:12, emoji:'🌱', title:'Jasmine',           latin:'Jasminum officinale',      description:'Jasmine is celebrated for its intensely sweet exotic fragrance — one of perfumery\'s most complex and coveted scents, requiring thousands of hand-picked flowers per ounce of essential oil. Small white star-shaped flowers cover climbing vines throughout summer. Jasmine tea, made by infusing green tea with jasmine blooms, is a beloved drink across Asia.',              tags:['fragrant','climbing','tea','night-blooming'], type:'Vine', keywords:['jasmine','white','fragrant','sweet','climbing','vine','tea','perfume','essential oil','night','summer','exotic','star','delicate','Asia'] },
  { id:13, emoji:'🍊', title:'Marigold',          latin:'Tagetes erecta',           description:'Marigolds glow with amber, orange, yellow, and red, and are among the easiest flowers to grow from seed. Their pungent scent deters garden pests naturally. Sacred in Hindu and Mexican traditions, they carpet altars, festivals, and Día de los Muertos celebrations in brilliant orange garlands. They symbolise warmth, creativity, and passion.',                        tags:['easy-grow','pest-deterrent','cultural'],  type:'Annual',    keywords:['marigold','orange','yellow','amber','pungent','companion planting','Hindu','Mexican','Day of the Dead','festival','warm','fiery','seeds','bright','easy'] },
  { id:14, emoji:'💙', title:'Forget-Me-Not',     latin:'Myosotis sylvatica',       description:'Forget-me-nots form clouds of tiny sky-blue flowers with a golden yellow eye in shady, moist cottage garden spots. Their name comes from a medieval legend of a drowning knight who threw a bouquet crying "forget me not." They symbolise true love, fidelity, and remembrance, often planted on loved ones\' graves.',                                                   tags:['tiny','blue','cottage-garden','sentimental'], type:'Annual', keywords:['forget-me-not','blue','tiny','sky','cottage','woodland','shade','fidelity','memory','remembrance','love','legend','loyal','small','romantic'] },
  { id:15, emoji:'🌷', title:'Freesia',           latin:'Freesia refracta',         description:'Freesias are slender-stemmed flowers with funnel-shaped blooms prized for their fresh citrus-sweet fragrance — often described as the most uplifting scent in floristry. Native to South Africa, they bloom in white, yellow, pink, orange, red, and purple. Each stem carries multiple buds opening successively, making them exceptional and long-lasting cut flowers.',    tags:['fragrant','citrusy','elegant','bouquet'],  type:'Bulb',     keywords:['freesia','fragrant','citrus','fresh','funnel','South Africa','white','yellow','pink','slender','uplifting','scented','bouquet','elegant','spring'] },
  { id:16, emoji:'🌸', title:'Magnolia',          latin:'Magnolia grandiflora',     description:'Magnolias are ancient flowering trees — they predate bees, having evolved for beetle pollination millions of years ago. Large waxy blooms in creamy white or shell pink appear in early spring on bare branches, making the tree seem to float with fragrant flowers. Southern magnolias with their glossy evergreen leaves are iconic symbols of the American South.',       tags:['ancient','tree','spring','southern'],     type:'Tree',      keywords:['magnolia','white','pink','waxy','ancient','tree','spring','fragrant','southern','USA','large','creamy','prehistoric','elegant','pure'] },
  { id:17, emoji:'💛', title:'Daffodil',          latin:'Narcissus pseudonarcissus',description:'Daffodils are golden heralds of spring, bright yellow trumpets among the first flowers after winter. William Wordsworth immortalised them dancing in the breeze by a lakeside. Easy to naturalise in grass or woodland, bulbs multiply each year. The Welsh daffodil is a national symbol worn proudly on St. David\'s Day each March.',                                    tags:['spring','yellow','easy','symbol'],        type:'Bulb',      keywords:['daffodil','narcissus','yellow','trumpet','spring','Wordsworth','Welsh','Wales','bulb','golden','cheerful','naturalise','woodland','early','bright'] },
  { id:18, emoji:'🌺', title:'Bird of Paradise',  latin:'Strelitzia reginae',       description:'Bird of Paradise flowers are dramatic architectural blooms mimicking a tropical bird in flight — vivid orange petals form the crest while blue-purple petals form the beak. Native to South Africa and the official flower of Los Angeles, they are incredibly long-lasting cut flowers that bring instant tropical drama and sculptural beauty to any arrangement.',           tags:['tropical','dramatic','architectural'],    type:'Perennial', keywords:['bird of paradise','orange','blue','tropical','dramatic','South Africa','Los Angeles','sculptural','architectural','exotic','bold','modern','striking','long-lasting','statement'] },
  { id:19, emoji:'🌷', title:'Ranunculus',        latin:'Ranunculus asiaticus',     description:'Ranunculus are the photographers\' darlings — tissue-paper-thin petals layered in countless concentric rings creating blooms that look almost too beautiful to be real. Often mistaken for peonies, they bloom in candy-bright coral, red, orange, yellow, cream, and burgundy. A darling of the wedding and floral design world with an excellent vase life.',             tags:['photogenic','layered','bridal','vibrant'], type:'Bulb',     keywords:['ranunculus','layers','petals','wedding','photogenic','coral','cream','burgundy','tissue paper','double','florist','beautiful','romantic','spring','cut flower'] },
  { id:20, emoji:'💗', title:'Cosmos',            latin:'Cosmos bipinnatus',        description:'Cosmos are airy, carefree flowers with feathery foliage and daisy-like blooms in the softest pinks, whites, corals, and wine-reds. Simply scatter seeds and watch them bloom all summer. Their name means "harmony" in Greek. Bees, butterflies, and hover flies adore them, making a cosmos patch a buzzing wildlife haven.',                                            tags:['easy-grow','airy','cottage-garden','wildlife'], type:'Annual', keywords:['cosmos','pink','airy','feathery','easy','scatter','bees','butterflies','wildlife','white','coral','wine','harmony','cottage','summer'] },

  // ── 21-30: Climbing & Shrubs ──
  { id:21, emoji:'🍃', title:'Sweet Pea',         latin:'Lathyrus odoratus',        description:'Sweet peas are delicate climbers with butterfly-shaped flowers in the softest pastels — pinks, lavenders, whites, and blues straight out of a watercolour painting. Their fragrance is extraordinary: sweet, powdery, nostalgic, capturing the very essence of an English cottage garden in summer. They must be picked regularly to keep blooming.',                        tags:['climbing','pastel','cottage-garden','fragrant'], type:'Annual', keywords:['sweet pea','fragrant','pastel','climbing','cottage','pink','lavender','blue','white','tender','nostalgic','summer','English','romantic','delicate'] },
  { id:22, emoji:'🌸', title:'Wisteria',          latin:'Wisteria sinensis',        description:'Wisteria is perhaps the most romantic climbing plant — cascading clusters of violet, lilac, or white flowers drip from pergolas and trellises like purple waterfalls in late spring. Their soft grape-like fragrance perfumes entire gardens. Native to China and Japan, they are celebrated in art and poetry for their ethereal beauty. Established vines live for centuries.', tags:['climbing','purple','cascading','romantic'], type:'Vine', keywords:['wisteria','purple','cascading','climbing','fragrant','vine','spring','romantic','Japan','China','pergola','violet','lilac','ethereal','century-old'] },
  { id:23, emoji:'🌼', title:'Chamomile',         latin:'Matricaria chamomilla',    description:'Chamomile looks like a field of miniature suns with bright yellow centres ringed by white petals on feathery apple-scented foliage. One of the world\'s most ancient healing herbs, it brews into a soothing tea that calms nerves, aids sleep, and settles stomachs. Sacred to the Norse sun god, it grows cheerfully in poor soil and self-seeds in meadows.',          tags:['medicinal','tea','soothing','wildflower'], type:'Annual', keywords:['chamomile','tea','soothing','calming','white','yellow','herbal','medicinal','sleep','apple','meadow','wildflower','ancient','healing','Norse'] },
  { id:24, emoji:'🔵', title:'Hydrangea',         latin:'Hydrangea macrophylla',    description:'Hydrangeas produce enormous mophead or lacecap flower clusters that change colour based on soil acidity — blue in acidic soil, pink in alkaline soil. This magical colour-changing quality fascinates gardeners everywhere. Their papery flowers age beautifully and dry well for wreaths. Popular in coastal cottage gardens, they represent gratitude, grace, and abundance.', tags:['colour-changing','large','cottage-garden'], type:'Shrub', keywords:['hydrangea','blue','pink','mophead','colour change','soil','acidic','alkaline','cluster','coastal','cottage','abundant','grace','papery','dries well'] },
  { id:25, emoji:'🌿', title:'Echinacea',         latin:'Echinacea purpurea',       description:'Echinacea, or coneflower, is a North American native wildflower with spiky orange-brown central cones surrounded by drooping purple or pink petals. Famous as an herbal remedy to boost immunity and fight colds, goldfinches feast on its seed heads in winter. It thrives in sunny borders and is virtually indestructible once established.',                          tags:['medicinal','native','wildlife','prairie'],type:'Perennial', keywords:['echinacea','coneflower','purple','pink','medicinal','immune','North America','prairie','goldfinch','seeds','bold','spiky','wildflower','herbal','tough'] },
  { id:26, emoji:'🌷', title:'Anemone',           latin:'Anemone coronaria',        description:'Anemones are jewel-like flowers with poppy-shaped petals in intense scarlet, deep purple, cobalt blue, and white, each centred with a dramatic black button of stamens. Hugely popular with florists for their striking contrast, in Greek myth they sprang from Aphrodite\'s tears. Nicknamed "windflowers" as their petals tremble in the slightest breeze.',           tags:['jewel-toned','dramatic','florist-favourite'], type:'Bulb', keywords:['anemone','red','purple','blue','black','poppy','jewel','dramatic','florist','windflower','spring','autumn','Greek myth','Aphrodite','bold'] },
  { id:27, emoji:'🍋', title:'Mimosa',            latin:'Acacia dealbata',          description:'Mimosa is the flower of International Women\'s Day in Italy and Russia — tiny fluffy pompoms of brilliant yellow on silver-grey feathery branches in late winter. Their honey-vanilla fragrance is intensely sweet and captured in famous perfumes. Seeing mimosa bloom is an instant mood-lifter, promising that spring is just around the corner.',                       tags:['early-blooming','yellow','fragrant','celebratory'], type:'Tree', keywords:['mimosa','yellow','fluffy','pompom','fragrant','winter','spring','Women\'s Day','Italian','honey','vanilla','silver','feathery','first flower','sunshine'] },
  { id:28, emoji:'🌸', title:'Camellia',          latin:'Camellia japonica',        description:'Camellias are the glamorous ladies of the winter garden — glossy evergreen shrubs with formal rose-like blooms in deep red, soft pink, and white when most plants are dormant. Coco Chanel\'s favourite flower and iconic symbol, camellias represent longevity and devotion in Japan. All tea comes from their relative Camellia sinensis.',                               tags:['winter','evergreen','elegant','tea'],     type:'Shrub',     keywords:['camellia','winter','pink','red','white','Chanel','elegant','tea','Japan','China','glossy','evergreen','longevity','devotion','formal'] },
  { id:29, emoji:'🌻', title:'Gerbera Daisy',     latin:'Gerbera jamesonii',        description:'Gerbera daisies are happiness made into a flower — large, perfectly symmetrical blooms in every shade: coral, crimson, tangerine, lemon, magenta, and white. One of the world\'s most popular cut flowers, they are incredibly cheerful and long-lasting in a vase. Native to South Africa, their bold cartoon-bright colours are a favourite among children.',             tags:['cheerful','colourful','cut-flower'],      type:'Perennial', keywords:['gerbera','daisy','bright','colourful','coral','orange','pink','yellow','white','cheerful','cut flower','symmetrical','happy','children','South Africa'] },
  { id:30, emoji:'💜', title:'Lavender Rose',     latin:'Rosa (lavender variety)',  description:'Lavender and lilac roses occupy a dreamy enchanting space between pink and purple — colours not found in wild roses, developed through careful hybridisation. They symbolise love at first sight, wonder, and enchantment. These roses carry a classic fragrance with unique bluish-lilac hues that photograph magnificently and hold colour beautifully when dried.',        tags:['romantic','rare','fragrant','purple-pink'], type:'Shrub', keywords:['lavender rose','lilac','purple','pink','rare','hybrid','enchanting','wonder','magical','first sight','love','fragrant','dreamy','romantic','unique'] },

  // ── 31-45: Wildflowers & Meadow ──
  { id:31, emoji:'🌾', title:'Foxglove',          latin:'Digitalis purpurea',       description:'Foxgloves are tall, dramatic wildflowers with tubular bells in purple, pink, and white, spotted with darker dots inside that guide bees. They are biennial, forming a rosette the first year then sending up a majestic spike in the second. The digitalis compound extracted from foxglove is a life-saving heart medication. They self-seed abundantly in woodland gardens.',  tags:['woodland','tall','biennial','medicinal'], type:'Biennial', keywords:['foxglove','purple','pink','tubular','bell','woodland','digitalis','heart','medicinal','biennial','tall','spike','self-seed','cottage','bees'] },
  { id:32, emoji:'🔴', title:'Poppy',             latin:'Papaver rhoeas',           description:'Poppies are a symbol of remembrance and restful sleep, their bright red tissue-paper petals unfurling from nodding hairy buds each summer. They colonise disturbed earth and battlefield meadows with ease, lending Remembrance Day its iconic imagery. The opium poppy has also shaped human history through both medicine and trade, while the Himalayan blue poppy is a true rarity.', tags:['wildflower','red','remembrance','fragile'], type:'Annual', keywords:['poppy','red','tissue paper','remembrance','wildflower','opium','Himalayan','blue','delicate','nodding','field','Flanders','sleep','medicine','meadow'] },
  { id:33, emoji:'🟣', title:'Allium',            latin:'Allium giganteum',         description:'Alliums are globe-shaped clusters of hundreds of tiny star-shaped flowers held aloft on tall straight stems, creating a lollipop effect in the garden. These ornamental onion relatives bloom in rich purple, lilac, and white. Their structural, architectural quality looks stunning in naturalistic planting schemes and their dried seed heads provide winter interest.',       tags:['architectural','structural','purple','bulb'], type:'Bulb', keywords:['allium','purple','globe','sphere','architectural','structural','onion','tall','stem','ornamental','spring','bulb','naturalistic','seed head','lavender'] },
  { id:34, emoji:'🌺', title:'Bougainvillea',     latin:'Bougainvillea glabra',     description:'Bougainvillea drapes walls and pergolas in vivid magenta, scarlet, orange, pink, and white. What appear to be its brightly coloured petals are actually papery bracts — the real flowers are tiny white tubes in the centre. A symbol of summer in Mediterranean and tropical countries, it thrives in full sun and dry conditions, rewarding neglect with spectacular colour.', tags:['climbing','tropical','vivid','Mediterranean'], type:'Vine', keywords:['bougainvillea','magenta','pink','red','tropical','Mediterranean','climbing','wall','pergola','bract','vivid','hot','summer','drought','spectacular'] },
  { id:35, emoji:'🌸', title:'Phlox',             latin:'Phlox paniculata',         description:'Phlox fills summer gardens with dome-shaped clusters of fragrant star-shaped flowers in pink, white, red, lilac, and bicolour. A favourite of cottage gardeners, their sweet fragrance carries beautifully on warm summer evenings. Creeping phlox tumbles over walls in spring with a carpet of bloom, while tall varieties are border mainstays beloved by butterflies.',      tags:['fragrant','cottage-garden','summer','butterfly'], type:'Perennial', keywords:['phlox','pink','white','fragrant','cottage','summer','butterfly','cluster','dome','border','creeping','wall','star','sweet','evening'] },
  { id:36, emoji:'💛', title:'Coreopsis',         latin:'Coreopsis tinctoria',      description:'Coreopsis, or tickseed, produces a nonstop show of cheerful daisy-like flowers in golden yellow, orange, and bi-colours with a dark burgundy eye. Incredibly tough and drought-tolerant, they bloom prolifically from late spring to autumn without deadheading. Native to North America, they attract butterflies and finches and naturalise beautifully in meadow gardens.',  tags:['cheerful','drought-tolerant','long-blooming','native'], type:'Perennial', keywords:['coreopsis','tickseed','yellow','golden','orange','burgundy','daisy','cheerful','drought','tough','butterfly','finch','meadow','nonstop','summer'] },
  { id:37, emoji:'🌸', title:'Stock',             latin:'Matthiola incana',         description:'Stock flowers are old-fashioned cottage favourites, their tall spikes packed with densely ruffled blooms in deep pink, clove-scented white, red, lilac, and yellow. Their clove-spicy fragrance is strongest in the evening, making them perfect for cutting and bringing indoors. Grown since Victorian times, they are prized by florists for their old-world charm.',       tags:['fragrant','cottage','Victorian','cutting'], type:'Annual', keywords:['stock','matthiola','fragrant','clove','pink','white','red','lilac','spiky','Victorian','cutting','evening','ruffled','old-fashioned','florist'] },
  { id:38, emoji:'💐', title:'Lisianthus',        latin:'Eustoma grandiflorum',     description:'Lisianthus, often called prairie gentian, produces multiple large blooms per stem resembling roses or peonies in lilac, purple, white, and pink with ruffled petals. They are long-lasting cut flowers that last up to three weeks in a vase. Native to the American prairies, they now star in luxury wedding bouquets and high-end floral arrangements worldwide.',         tags:['luxurious','long-lasting','bridal','ruffled'], type:'Annual', keywords:['lisianthus','gentian','prairie','purple','lilac','white','ruffled','wedding','luxury','long-lasting','rose-like','peony-like','elegant','florist','bouquet'] },
  { id:39, emoji:'🌼', title:'Celandine',         latin:'Chelidonium majus',        description:'Lesser celandine is one of Britain\'s first spring wildflowers, its small star-shaped golden petals gleaming from woodland floors and hedgerows from February. Wordsworth wrote three poems in its honour and requested it carved on his tombstone. It opens its petals in sunshine and closes them at night, a behaviour called nyctinasty.',                              tags:['wildflower','spring','woodland','early'],  type:'Perennial', keywords:['celandine','golden','yellow','star','spring','woodland','early','Wordsworth','British','nyctinasty','wildflower','hedgerow','small','sun','first'] },
  { id:40, emoji:'🌸', title:'Bleeding Heart',   latin:'Lamprocapnos spectabilis',  description:'Bleeding Heart produces arching sprays of perfectly heart-shaped flowers in rose-pink or white, each with a protruding white inner petal resembling a droplet. One of spring\'s most romantic and distinctive flowers, it thrives in shady woodland gardens. The entire plant is toxic but its theatrical beauty makes it a beloved cottage garden classic.',                 tags:['romantic','shade-loving','unusual','spring'], type:'Perennial', keywords:['bleeding heart','pink','white','heart','arching','spray','shade','woodland','romantic','toxic','spring','distinctive','cottage','theatrical','beautiful'] },
  { id:41, emoji:'🟠', title:'Crocosmia',        latin:'Crocosmia x crocosmiiflora',description:'Crocosmia sends up arching branched stems of tubular orange, flame-red, and yellow flowers in late summer, evoking a firework display in the border. Originally from South Africa, the vibrant blooms are beloved by hummingbirds and bees. Their sword-like foliage is ornamental year-round and the corms multiply freely to create bold, dramatic clumps.',              tags:['bold','summer','orange','wildlife'],      type:'Corm',      keywords:['crocosmia','orange','red','yellow','tubular','arching','summer','hummingbird','bee','South Africa','bold','dramatic','sword','corm','late summer'] },
  { id:42, emoji:'💛', title:'Black-Eyed Susan',  latin:'Rudbeckia hirta',          description:'Black-eyed Susans are cheerful wildflowers with golden-yellow petals surrounding a prominent dark chocolate-brown central cone. Native to North America, they bloom from late summer into autumn, providing rich colour when most flowers fade. Butterflies and bees adore them, and their seed heads attract goldfinches. They are virtually care-free and tolerate drought well.',tags:['wildflower','native','autumn','wildlife'], type:'Perennial', keywords:['black-eyed susan','rudbeckia','yellow','golden','brown','cone','wildflower','native','autumn','butterfly','bee','goldfinch','drought','care-free','summer'] },
  { id:43, emoji:'🌸', title:'Astilbe',           latin:'Astilbe x arendsii',       description:'Astilbe produces feathery, plume-like flower heads in white, pink, red, and lilac above handsome fern-like foliage. One of the best flowering plants for shady, moist spots, they bring a romantic, airy quality to woodland gardens. Their dried plumes persist into autumn and winter, turning russet-brown and providing structural interest against frost.',               tags:['shade-loving','feathery','pink','woodland'], type:'Perennial', keywords:['astilbe','plume','feathery','pink','red','white','shade','moist','woodland','romantic','fern','autumn','dried','structural','garden'] },
  { id:44, emoji:'🌺', title:'Dahlia',            latin:'Dahlia pinnata',           description:'Dahlias are the showoffs of the autumn garden, blooming in a staggering variety of forms — pompon, cactus, dinner-plate, ball, and collarette — in every colour except blue. Their dinner-plate varieties can exceed thirty centimetres across. Originally from Mexico, dahlias fuel a passionate collector culture and are one of the most popular exhibition flowers worldwide.', tags:['autumn','bold','collector','Mexico'],     type:'Tuber',     keywords:['dahlia','autumn','colourful','Mexico','dinner-plate','pompom','cactus','large','bold','exhibition','collector','tuber','summer','September','variety'] },
  { id:45, emoji:'🌾', title:'Agapanthus',        latin:'Agapanthus africanus',      description:'Agapanthus, the African lily, carries globe-shaped clusters of tubular blue or white flowers atop tall, strap-leaved clumps. A symbol of African summers, it is treasured in coastal gardens for its tolerance of salt wind and drought. The stunning blue varieties are among the purest blues in horticulture and look spectacular against white-painted garden walls.',       tags:['blue','coastal','dramatic','South Africa'], type:'Perennial', keywords:['agapanthus','blue','white','African lily','globe','coastal','drought','salt','strap','tall','summer','cluster','pure blue','spectacular','South Africa'] },

  // ── 46-60: Herbs, Wildflowers, Cottage ──
  { id:46, emoji:'🍃', title:'Borage',            latin:'Borago officinalis',       description:'Borage produces star-shaped electric-blue flowers that are edible and taste faintly of cucumber. A cottage garden herb grown since antiquity for its medicinal and culinary uses, its flowers freeze beautifully into ice cubes for summer drinks. Borage is an excellent companion plant, deterring aphids and attracting bees en masse. It self-seeds with great enthusiasm.',    tags:['edible','blue','herb','companion plant'], type:'Annual', keywords:['borage','blue','star','edible','cucumber','herb','bee','companion','self-seed','cottage','summer','ice cube','drink','medicinal','annual'] },
  { id:47, emoji:'💜', title:'Viola',             latin:'Viola tricolor',           description:'Violas and pansies are endearing little flowers with velvety, face-like markings in every conceivable colour. Hardy enough to flower through winter and spring, they are the workhorses of seasonal bedding. Their flowers are edible and used to decorate salads and desserts. The viola\'s heart-shaped petals have symbolised free thought and remembrance for centuries.',       tags:['edible','winter','cheerful','small'],    type:'Annual',    keywords:['viola','pansy','purple','yellow','white','edible','winter','velvety','face','cottage','bedding','heart','small','cheerful','hardy'] },
  { id:48, emoji:'🌸', title:'Columbine',         latin:'Aquilegia vulgaris',       description:'Columbines are wildly intricate flowers with backward-pointing nectar spurs that evolved specifically for long-tongued insects. They dance in the breeze on wire-thin stems in shades of purple, pink, blue, white, and yellow. Naturalising freely in woodland gardens, they inspired medieval art and the name aquilegia — from the Latin for eagle, referencing their talon-like spurs.',tags:['intricate','woodland','wild','cottage'],  type:'Perennial', keywords:['columbine','aquilegia','purple','blue','pink','spur','woodland','intricate','medieval','cottage','self-seed','nectar','eagle','delicate','spring'] },
  { id:49, emoji:'🌼', title:'Oxeye Daisy',       latin:'Leucanthemum vulgare',     description:'Oxeye daisies are the romantic wildflowers of summer meadows, their large white petals surrounding golden yellow discs swaying in the breeze. They have naturalised in meadows across the Northern Hemisphere and provide an invaluable food source for bees and butterflies. Their cheerful simplicity has made them a cottage garden favourite and a symbol of innocent beauty.',   tags:['meadow','wildflower','white','romantic'], type:'Perennial', keywords:['oxeye daisy','white','yellow','meadow','wildflower','romantic','cottage','bee','butterfly','summer','naturalised','simple','innocent','disc','sway'] },
  { id:50, emoji:'🌺', title:'Salvia',            latin:'Salvia officinalis',       description:'Salvias encompass hundreds of species from culinary sage to fiery red tropical beauties. Their tubular flowers are magnets for bees, hummingbirds, and butterflies. Deep blue salvias like Salvia guaranitica bring rich cobalt tones to late summer borders, while the scarlet Salvia splendens blazes in bedding schemes. All salvias share the characteristic square stems of the mint family.',tags:['bee-friendly','blue','red','herb'],       type:'Perennial', keywords:['salvia','sage','blue','red','tubular','bee','hummingbird','butterfly','herb','cobalt','scarlet','summer','mint family','medicinal','aromatic'] },
  { id:51, emoji:'💙', title:'Delphinium',        latin:'Delphinium elatum',        description:'Delphiniums are the grand aristocrats of the cottage garden, their towering spikes reaching two metres and packed with intensely blue, purple, pink, or white flowers. Their vivid blue tones are unmatched in the garden. They are pollinated by bumblebees and provide a dramatic vertical accent in borders. The name comes from the Greek for dolphin, referencing the bud shape.',tags:['tall','blue','dramatic','cottage'],       type:'Perennial', keywords:['delphinium','blue','purple','tall','spike','cottage','aristocratic','vertical','bumblebee','dramatic','intense','violet','border','summer','June'] },
  { id:52, emoji:'🌸', title:'Lathyrus',          latin:'Lathyrus latifolius',      description:'Perennial sweet peas or everlasting peas produce smaller flowers than their annual cousins but return reliably each year, clambering up supports with tendrils. They bloom in rich magenta-pink, lilac, and white through summer and are completely unfussy about soil. Unlike annual sweet peas, they have little fragrance, but their vigour and longevity make them garden workhorses.',tags:['perennial','climbing','hardy','summer'],  type:'Perennial', keywords:['lathyrus','perennial sweet pea','pink','magenta','lilac','climbing','tendril','hardy','summer','reliable','unfussy','border','cottage','vigorous','returning'] },
  { id:53, emoji:'🟡', title:'Evening Primrose',  latin:'Oenothera biennis',        description:'Evening primrose opens its large, satiny yellow blooms at dusk, releasing a sweet lemon fragrance into the evening air to attract night-flying moths. This biennial wildflower has been used medicinally for centuries, and its seed oil is rich in gamma-linolenic acid, prized in cosmetics and health supplements. Its luminous pale yellow flowers glow beautifully in twilight gardens.',tags:['night-blooming','yellow','medicinal','wild'],type:'Biennial', keywords:['evening primrose','yellow','night','moth','fragrant','lemon','dusk','medicinal','oil','GLA','cosmetic','biennial','twilight','glow','wild'] },
  { id:54, emoji:'🌸', title:'Penstemon',         latin:'Penstemon digitalis',      description:'Penstemons are North American wildflowers producing elegant tubular flowers in rich pinks, reds, purples, and white with a distinctive whiskered throat. They are favourite flowers of hummingbirds and bumblebees and are reliable, long-blooming perennials for sunny, well-drained borders. Their semi-evergreen foliage is attractive year-round.',                           tags:['hummingbird','tubular','pink','summer'],  type:'Perennial', keywords:['penstemon','pink','red','purple','tubular','bearded','hummingbird','bee','North American','wildflower','sunny','long-blooming','perennial','whiskered','border'] },
  { id:55, emoji:'💜', title:'Verbena',           latin:'Verbena bonariensis',      description:'Verbena bonariensis is the transparent plant — its clusters of tiny purple flowers are held aloft on rigid, branched stems so tall and airy they let the garden be seen through them. A favourite of contemporary garden designers, bees and butterflies mob the clusters. Self-seeding freely in gravel and borders, it bridges seasons from summer through autumn frost.',          tags:['airy','purple','self-seeding','butterfly'], type:'Perennial', keywords:['verbena','purple','airy','transparent','self-seeding','butterfly','bee','contemporary','gravel','autumn','tall','clusters','branched','designer','small flowers'] },
  { id:56, emoji:'🌺', title:'Kniphofia',         latin:'Kniphofia uvaria',         description:'Red hot pokers are boldly architectural plants with upright torch-like flower heads in gradients of scarlet, orange, and yellow. Their vivid, flame-coloured spikes attract hummingbirds and add drama to late-season borders. Native to Africa, they are drought-tolerant and thrive in hot, sunny spots. The colour transitions from bud to open flower create a striking two-toned effect.', tags:['bold','architectural','orange','hummingbird'],type:'Perennial', keywords:['kniphofia','red hot poker','orange','red','yellow','torch','spike','hummingbird','dramatic','Africa','drought','sunny','two-toned','bold','architectural'] },
  { id:57, emoji:'🌸', title:'Scabious',          latin:'Scabiosa columbaria',      description:'Scabious, or pincushion flower, produces delicate lilac-blue domes on wiry stems that float above grassy foliage like little parasols. One of the most important wildflowers for bees and butterflies, its nectar is accessible to short-tongued insects. It blooms for months from midsummer to autumn and self-seeds gently in gravel gardens and meadow schemes.',               tags:['wildflower','lilac','bee-friendly','meadow'], type:'Perennial', keywords:['scabious','pincushion','lilac','blue','delicate','dome','wiry','bee','butterfly','meadow','gravel','summer','autumn','long-blooming','wildflower'] },
  { id:58, emoji:'🌾', title:'Teasel',            latin:'Dipsacus fullonum',        description:'Teasels are architectural biennial wildflowers with egg-shaped prickly heads that produce a ring of tiny purple flowers working upwards. After flowering, their sculptural dried seed heads stand through winter and are irresistible to goldfinches. They naturalise in wild gardens and their prickly texture was historically used to raise the nap on woollen cloth.',               tags:['architectural','wildlife','biennial','winter'], type:'Biennial', keywords:['teasel','purple','prickly','goldfinch','architectural','biennial','winter','seed head','naturalise','wool','historic','wild','structural','sculptural','birds'] },
  { id:59, emoji:'🌸', title:'Campion',           latin:'Silene dioica',            description:'Red campion is a joyful wildflower of hedgerows and woodland edges, its rosy-pink star-shaped flowers brightening shady spots from spring to autumn. It hybridises freely with white campion to produce pale pink intermediates. A valuable nectar source for bumblebees and long-tongued insects, it self-seeds freely and naturalises beautifully in wild gardens.',               tags:['wildflower','pink','woodland','bee-friendly'], type:'Perennial', keywords:['campion','pink','red','wildflower','woodland','hedgerow','bee','spring','autumn','star','self-seed','naturalise','shady','rosy','hybrid'] },
  { id:60, emoji:'💛', title:'Yarrow',            latin:'Achillea millefolium',      description:'Yarrow is a tough, aromatic wildflower with flat-topped clusters of tiny flowers in white, yellow, pink, and red above feathery, fernlike foliage. Ancient Greek legend has Achilles use yarrow to heal his warriors\' wounds, and it remains a folk remedy for cuts today. A magnet for beneficial insects, it tolerates drought and poor soil while blooming all summer.',     tags:['medicinal','wildflower','flat-topped','bee-friendly'], type:'Perennial', keywords:['yarrow','achillea','white','yellow','pink','flat-topped','feathery','medicinal','Achilles','wildflower','drought','bee','butterfly','aromatic','summer'] },

  // ── 61-80: Tropical & Exotic ──
  { id:61, emoji:'🌺', title:'Plumeria',          latin:'Plumeria rubra',           description:'Plumeria, or frangipani, produces clusters of incredibly fragrant, waxy flowers in white, yellow, pink, and red with a golden centre. Originating from Central America, it is deeply woven into Hawaiian culture as the source of flower leis. The scent — sweet, creamy, and tropical — is one of the most beloved in the world and used extensively in luxury perfumery.',    tags:['tropical','fragrant','Hawaii','exotic'],  type:'Tree',      keywords:['plumeria','frangipani','white','yellow','pink','fragrant','tropical','Hawaii','lei','waxy','Central America','exotic','perfume','creamy','luxury'] },
  { id:62, emoji:'🌸', title:'Protea',            latin:'Protea cynaroides',        description:'The king protea is South Africa\'s national flower and one of the most dramatic blooms in the world — a giant sunburst of silky petals surrounding a central cone, in shades of dusty pink, cream, and burgundy. Ancient and prehistoric, proteas evolved before bees existed. They are long-lasting cut flowers and symbols of diversity and transformation.',               tags:['dramatic','South Africa','prehistoric','architectural'], type:'Shrub', keywords:['protea','king protea','pink','cream','burgundy','South Africa','national flower','dramatic','large','prehistoric','ancient','cut flower','cone','silky','symbol'] },
  { id:63, emoji:'🌺', title:'Heliconia',         latin:'Heliconia rostrata',       description:'Heliconias are bold tropical beauties with dramatic hanging or upright bracts in vivid red, orange, and yellow that shelter inconspicuous true flowers. Called lobster claws or parrot flowers, they are essential to rainforest ecosystems, providing nectar for hummingbirds and habitat for insects. Their thick, banana-like leaves are used throughout the tropics for food wrapping.', tags:['tropical','bold','hummingbird','rainforest'], type:'Perennial', keywords:['heliconia','lobster claw','orange','red','yellow','tropical','hummingbird','rainforest','bract','dramatic','banana-like','bold','vivid','hanging','exotic'] },
  { id:64, emoji:'🌸', title:'Anthurium',         latin:'Anthurium andraeanum',     description:'Anthuriums produce waxy, heart-shaped spathes in glossy red, pink, white, and purple surrounding an elongated spadix. Their lacquered appearance is almost unreal. Native to the rainforests of Central and South America, they are among the longest-lasting cut flowers, staying fresh for up to eight weeks. They represent hospitality and are a luxury floristry staple.',    tags:['tropical','glossy','long-lasting','luxury'], type:'Perennial', keywords:['anthurium','red','pink','white','heart-shaped','waxy','glossy','spadix','tropical','long-lasting','luxury','hospitality','rainforest','cut flower','modern'] },
  { id:65, emoji:'💛', title:'Alstroemeria',      latin:'Alstroemeria aurea',       description:'Alstroemeria, the Peruvian lily, produces masses of funnel-shaped flowers in orange, yellow, pink, red, and white with intricate dark veining on the inner petals. One of the most popular florist flowers in the world, they last up to three weeks in a vase — exceptionally long-lived. They symbolise friendship, devotion, and fortune in the language of flowers.',        tags:['long-lasting','friendship','florist','colorful'], type:'Perennial', keywords:['alstroemeria','Peruvian lily','orange','pink','yellow','red','funnel','striped','veined','long-lasting','florist','friendship','devotion','popular','cut flower'] },
  { id:66, emoji:'🌺', title:'Torch Ginger',      latin:'Etlingera elatior',        description:'Torch ginger is a magnificent tropical plant, its bright waxy flower heads resembling glowing red or pink torches on tall cane-like stems. The flower buds are a staple ingredient in Malaysian and Indonesian cuisine, lending a floral-ginger flavour to curries and salads. The extraordinary blooms last for weeks as cut flowers and are extraordinary in tropical wedding arrangements.', tags:['tropical','culinary','dramatic','pink'],   type:'Perennial', keywords:['torch ginger','ginger','red','pink','tropical','waxy','dramatic','Malaysian','Indonesian','culinary','edible','large','exotic','wedding','cut flower'] },
  { id:67, emoji:'🌸', title:'Lotus',             latin:'Nelumbo nucifera',         description:'The lotus flower rises pristine from muddy water each morning, its pink and white petals perfectly clean and dry due to a microscopic self-cleaning surface structure. Sacred in Buddhism and Hinduism, it represents spiritual awakening, purity of mind, and rebirth. Every part of the lotus plant is edible — seeds, roots, and petals — and has been used in Asian medicine for millennia.',tags:['sacred','symbolic','aquatic','spiritual'],type:'Aquatic',   keywords:['lotus','pink','white','sacred','Buddhist','Hindu','spiritual','purity','rebirth','aquatic','self-cleaning','edible','rhizome','seeds','muddy water'] },
  { id:68, emoji:'🌼', title:'Calendula',         latin:'Calendula officinalis',    description:'Calendula, or pot marigold, produces bright orange and yellow flowers that close at night and on cloudy days, tracking the sun — giving rise to its old name "Mary\'s gold". One of the most medicinal plants in history, its petals are anti-inflammatory and used in skin creams, ointments, and teas. Edible petals add a saffron-like colour and mild flavour to salads.',  tags:['medicinal','edible','orange','easy-grow'],type:'Annual',    keywords:['calendula','pot marigold','orange','yellow','edible','medicinal','skin','anti-inflammatory','petals','tea','saffron','sun-tracking','easy','annual','kitchen garden'] },
  { id:69, emoji:'💜', title:'Globe Thistle',     latin:'Echinops ritro',           description:'Globe thistles produce perfectly spherical metallic blue flower heads on steel-grey stems that look more sculptural than botanical. They are loved by bees and butterflies and are drought-tolerant, native to rocky European and Asian habitats. Their steely blue colour is rare and striking in the late summer border, and they dry magnificently for winter arrangements.',    tags:['architectural','blue','drought-tolerant','sculptural'], type:'Perennial', keywords:['globe thistle','echinops','blue','metallic','sphere','architectural','sculptural','drought','bee','butterfly','summer','dried','steel','border','striking'] },
  { id:70, emoji:'🌸', title:'Amaryllis',         latin:'Hippeastrum',              description:'Amaryllis bulbs produce spectacular trumpets of bloom in deep red, candy-stripe, salmon, white, and pink in the depths of winter, making them the festive season\'s most theatrical houseplant. A single bulb can carry four enormous blooms on a hollow stem up to seventy centimetres tall. Originally from South American savannahs, they have been hybridised for maximum flamboyance.',tags:['winter','bold','houseplant','bulb'],      type:'Bulb',      keywords:['amaryllis','hippeastrum','red','pink','white','striped','trumpet','winter','Christmas','bulb','houseplant','dramatic','tall','hollow stem','South America'] },
  { id:71, emoji:'🌺', title:'Passion Flower',    latin:'Passiflora caerulea',      description:'Passion flowers are extraordinary climbing plants with flowers of extraordinary, alien complexity — concentric rings of white petals and blue corona filaments surrounding a central structure of scientific precision. Spanish missionaries believed the flower depicted the crucifixion of Christ. The plant produces edible orange fruits and grows vigorously on sunny walls, attracting bees.',tags:['climbing','exotic','symbolic','unusual'], type:'Vine', keywords:['passion flower','passiflora','blue','white','complex','alien','climbing','vine','crucifixion','Christian','symbolic','edible','fruit','bee','extraordinary'] },
  { id:72, emoji:'💛', title:'Kangaroo Paw',      latin:'Anigozanthos flavidus',    description:'Kangaroo paw is an extraordinary Australian wildflower named for its distinctive claw-like tubular flowers covered in dense velvety hair in red-and-green, yellow, pink, and orange. Beloved by nectar-feeding birds, these long-lasting cut flowers are increasingly popular in contemporary floristry for their unusual form and vibrant colour contrasts.',                   tags:['Australian','unusual','cut flower','vivid'], type:'Perennial', keywords:['kangaroo paw','Australian','red','green','yellow','orange','tubular','velvety','claw','nectar','bird','long-lasting','cut flower','unusual','florist'] },
  { id:73, emoji:'🌸', title:'Protea Repens',     latin:'Protea repens',            description:'Protea repens, or sugarbush, is one of South Africa\'s most important fynbos plants. Its cone-shaped flowers ooze nectar so profusely that traditional communities collected the sugary liquid as a sweetener called "bossiestroop". Sunbirds are its principal pollinators, attracted by the deep pink, cream, and red flower heads throughout winter and spring.',              tags:['South Africa','nectar','wildlife','unusual'], type:'Shrub', keywords:['protea repens','sugarbush','pink','cream','South Africa','fynbos','nectar','sunbird','sweet','winter','spring','cone','dramatic','large','pollinator'] },
  { id:74, emoji:'🌼', title:'Nemesia',           latin:'Nemesia strumosa',         description:'Nemesias are small, cheerful annuals with a remarkable colour range — from pure white through all shades of yellow, orange, pink, red, and bicoloured combinations with a contrasting throat. They produce a profusion of small orchid-like blooms through spring and early summer and are outstanding in window boxes, hanging baskets, and container displays.',                tags:['container','colorful','small','spring'],  type:'Annual',    keywords:['nemesia','colourful','small','orchid-like','annual','container','hanging basket','window box','spring','cheerful','bicoloured','profuse','yellow','pink','orange'] },
  { id:75, emoji:'💜', title:'Nigella',           latin:'Nigella damascena',        description:'Nigella, or love-in-a-mist, produces delicate blue, white, or pink flowers surrounded by a haze of intricate feathery bracts that give it an ethereal misty appearance. The inflated seed pods that follow are equally ornamental — striped and papery, they dry beautifully for arrangements. It self-seeds prolifically and blooms for months from a simple scattered sowing.',  tags:['ethereal','cottage-garden','self-seeding','blue'], type:'Annual', keywords:['nigella','love in a mist','blue','white','feathery','bract','ethereal','misty','seed pod','self-seed','annual','cottage','delicate','papery','ornamental'] },
  { id:76, emoji:'🌸', title:'Lavatera',          latin:'Lavatera trimestris',      description:'Annual lavatera produces large, silky funnel-shaped flowers in deep rose-pink, soft pink, and white all summer long on bushy plants that can reach a metre in height. They are incredibly easy to grow from direct-sown seed, establishing rapidly and filling gaps in borders with reliable colour. Their blooms resemble a large hollyhock and are attractive to bees.',           tags:['easy-grow','pink','summer','annual'],     type:'Annual',    keywords:['lavatera','pink','white','funnel','silk','mallow','annual','easy','bee','gap filler','border','self-seed','cottage','prolific','summer'] },
  { id:77, emoji:'🌺', title:'Celosia',           latin:'Celosia argentea',         description:'Celosia, or cockscomb, produces unique velvety flower forms — either densely brain-like crested plumes or feathery spires — in vivid magenta, red, orange, yellow, and pink. Originating in tropical Africa and Asia, these long-lasting cut flowers hold their extraordinary colour for weeks when dried. Their velvet texture is unlike any other flower in horticulture.',  tags:['unusual','tropical','vivid','long-lasting'], type:'Annual', keywords:['celosia','cockscomb','velvety','brain-like','plume','magenta','red','orange','vivid','tropical','dried','long-lasting','unusual','texture','Africa'] },
  { id:78, emoji:'🌾', title:'Sea Holly',         latin:'Eryngium maritimum',       description:'Sea holly is a coastal wildflower of extraordinary architectural beauty, its steely blue, egg-shaped flower heads surrounded by spiky silver-blue bracts creating a sculptural metallic effect. Drought-tolerant and salt-resistant, it grows in coastal dunes and is beloved in contemporary planting design for its architectural form, rare steel-blue colour, and bee-attracting flowers.',tags:['coastal','architectural','blue','drought-tolerant'], type:'Perennial', keywords:['sea holly','eryngium','blue','steel','silver','spiky','coastal','architectural','drought','salt','bee','sculptural','metallic','dunes','contemporary'] },
  { id:79, emoji:'💐', title:'Muscari',           latin:'Muscari armeniacum',       description:'Grape hyacinths carpet the ground in spring with dense, conical clusters of tiny cobalt-blue bells that resemble a bunch of grapes, filling the air with a sweet musky-violet fragrance. Among the most reliable spring bulbs, they naturalise freely and multiply to create drifts of intense blue beneath deciduous trees. They are among the very few truly blue spring flowers.',tags:['spring','blue','bulb','fragrant'],        type:'Bulb',      keywords:['muscari','grape hyacinth','blue','cobalt','bells','spring','fragrant','bulb','naturalise','drift','tiny','cluster','cone','violet','musky'] },
  { id:80, emoji:'🌸', title:'Snapdragon',        latin:'Antirrhinum majus',        description:'Snapdragons are loved by children and gardeners alike for their hinged, dragon-mouth blooms that snap open when squeezed. They produce tall spikes of densely packed flowers in every colour including bicolours, and their sweet scent perfumes cottage gardens from spring through autumn. Cool-season flowers, they thrive in spring and autumn and tolerate light frost.',       tags:['cottage','colorful','fragrant','cool-season'], type:'Annual', keywords:['snapdragon','antirrhinum','pink','red','yellow','white','snap','mouth','spike','fragrant','cottage','bicolour','cool-season','tall','spring'] },

  // ── 81-100: Bulbs, Climbers & More ──
  { id:81, emoji:'💛', title:'Canna Lily',        latin:'Canna indica',             description:'Canna lilies are dramatic tropical plants with enormous paddle-shaped foliage in green, bronze, or striped, topped by vivid orchid-like flowers in red, orange, yellow, and pink. They create instant tropical drama in temperate gardens through summer and autumn. The rhizomes of some species produce arrowroot starch, a valuable gluten-free food.',                          tags:['tropical','bold','summer','dramatic'],    type:'Rhizome',   keywords:['canna lily','tropical','red','orange','yellow','paddle','leaf','bold','dramatic','summer','rhizome','arrowroot','starch','bronze','vivid'] },
  { id:82, emoji:'🌸', title:'Cyclamen',          latin:'Cyclamen persicum',        description:'Cyclamen are charming flowers with swept-back petals like shooting stars in white, pink, red, and purple. They bloom through winter and spring when the garden is bare, making them invaluable for cold-season colour. Hardy species naturalise under deciduous trees in woodland gardens. Their intricately marbled foliage is ornamental in its own right throughout the year.',      tags:['winter','woodland','elegant','marbled'],  type:'Tuber',     keywords:['cyclamen','pink','white','red','swept-back','star','winter','woodland','marbled','foliage','hardy','cool','elegant','shade-loving','autumn'] },
  { id:83, emoji:'🌺', title:'Gazania',           latin:'Gazania rigens',           description:'Gazanias are South African sun-worshippers that open their large daisy-like flowers only in full sunshine, their dramatic petals boldly striped and marked in orange, yellow, and pink around a contrasting dark centre. They thrive in dry, sandy conditions and coastal gardens where other plants struggle. Their vivid colours are among the most saturated in the plant kingdom.',tags:['sun-loving','drought','vivid','South Africa'], type:'Perennial', keywords:['gazania','orange','yellow','pink','striped','daisy','South Africa','sun','drought','coastal','sandy','vivid','bold','saturated','warm'] },
  { id:84, emoji:'💙', title:'Love-in-a-Mist',    latin:'Nigella sativa',           description:'Love-in-a-mist is closely related to garden nigella, producing black seed pods that are harvested as nigella seeds — the "black seed" revered in Islamic medicine and used in Middle Eastern cooking for its peppery, onion-like flavour. The delicate blue flowers embedded in feathery bracts are equally beautiful in borders and cutting gardens.',                         tags:['culinary','blue','edible','unusual'],     type:'Annual',    keywords:['love in a mist','nigella','black seed','blue','culinary','Islamic medicine','feathery','edible','spice','peppery','annual','cottage','delicate','seeds','cutting'] },
  { id:85, emoji:'🌸', title:'Heather',           latin:'Calluna vulgaris',         description:'Heather carpets the moorlands of Scotland and northern Europe in purple, pink, and white from late summer into autumn, creating some of the most iconic and atmospheric landscapes in the world. It is the national flower of Norway and loved by bees, who produce a distinctive, richly flavoured monofloral heather honey. Compact cultivars are popular in winter garden displays.',tags:['moorland','Scottish','autumn','bee-friendly'], type:'Shrub', keywords:['heather','calluna','purple','pink','white','moorland','Scottish','Norway','bee','honey','autumn','carpet','compact','winter','atmosphere'] },
  { id:86, emoji:'💛', title:'Lysimachia',        latin:'Lysimachia punctata',      description:'Yellow loosestrife produces upright spikes of bright starry yellow flowers through summer, spreading gently to form bold, cheerful clumps in moist borders and pondside plantings. It provides good nectar for bees and is excellent for naturalising in wilder garden areas. Its stems were historically stuffed in horse collars — the "loosestrife" name comes from the belief it calmed oxen.',tags:['yellow','moist','summer','naturalising'],  type:'Perennial', keywords:['lysimachia','loosestrife','yellow','star','summer','moist','pondside','naturalise','bee','clump','spike','upright','bright','historic','border'] },
  { id:87, emoji:'🌸', title:'Monarda',           latin:'Monarda didyma',           description:'Bee balm or bergamot produces spectacular tufted flower heads in rich red, pink, purple, and white that buzz with bumblebees all summer. The aromatic leaves smell strongly of bergamot orange and were used by Native Americans to make Oswego tea. A magnet for hummingbirds, bees, and butterflies, it is one of the most wildlife-valuable garden plants in North America.',tags:['bee-friendly','hummingbird','aromatic','North American'], type:'Perennial', keywords:['monarda','bee balm','bergamot','red','pink','purple','tufted','aromatic','hummingbird','bumblebee','butterfly','Oswego tea','Native American','summer','wildflower'] },
  { id:88, emoji:'🌺', title:'Catmint',           latin:'Nepeta x faassenii',       description:'Catmint forms billowing mounds of silver-grey foliage covered in spikes of soft lavender-blue flowers from late spring through summer. Irresistible to bees and — famously — cats, who roll ecstatically in it, it is one of the most effective border edging plants, softening hard lines with its hazy colour and relaxed habit. It can be cut back hard for a second flush.',tags:['fragrant','blue','border','bee-friendly'], type:'Perennial', keywords:['catmint','nepeta','lavender','blue','silver','grey','cats','bees','border','edging','mound','aromatic','soft','cottage','summer'] },
  { id:89, emoji:'💜', title:'Liatris',           latin:'Liatris spicata',          description:'Liatris, or blazing star, produces tall wand-like spikes of fluffy purple or white flowers that uniquely open from the top downwards. An American prairie native, it is extraordinarily drought-tolerant and attracts monarch butterflies and bees in large numbers. It is also an excellent and long-lasting cut flower, and the corms are a valuable food source for voles and field mice.',tags:['prairie','purple','butterfly','unusual'], type:'Corm', keywords:['liatris','blazing star','purple','white','spike','top-down','prairie','monarch butterfly','bee','drought','American','cut flower','long-lasting','corm','unusual'] },
  { id:90, emoji:'🌸', title:'Nicotiana',         latin:'Nicotiana alata',          description:'Flowering tobacco, or nicotiana, produces tubular trumpet-shaped flowers in white, pink, red, and green that release an intensely sweet jasmine-like fragrance in the evening, attracting hawkmoths. It comes from South America and the enormous tender shrub Nicotiana sylvestris produces long, pendulous white trumpets of surpassing elegance. Perfect planted beside garden seating to catch the evening scent.',tags:['fragrant','evening','white','night-scented'], type:'Annual', keywords:['nicotiana','tobacco','white','pink','fragrant','evening','hawkmoth','jasmine-like','tubular','sweet','night','South America','elegant','seating','scent'] },
  { id:91, emoji:'🌼', title:'Osteospermum',      latin:'Osteospermum ecklonis',    description:'African daisies produce masses of large daisy-like flowers in white, yellow, pink, and purple, with an extraordinary spoon-shaped or quilled petal variety unique in horticulture. Incredibly free-flowering from spring to the first frost, they thrive in hot sunny spots and are superb container plants. Originally from South Africa, they are now essential in summer bedding.',tags:['South Africa','summer','container','free-flowering'], type:'Perennial', keywords:['osteospermum','African daisy','white','pink','yellow','purple','spoon-shaped','free-flowering','summer','container','frost','hot','sunny','bedding','South Africa'] },
  { id:92, emoji:'🌸', title:'Tweedia',           latin:'Tweedia caerulea',         description:'Tweedia is a charming small climbing plant that produces starfish-shaped flowers in a rare and precious true sky-blue that ages to lilac then pink, meaning each stem carries flowers in three colours simultaneously. This Brazilian native is much sought after by florists for its unusual colouring. It is tender and best grown in a warm, sheltered spot or conservatory.',tags:['blue','rare','small','unusual'],          type:'Climber',   keywords:['tweedia','blue','sky-blue','lilac','pink','starfish','rare','florist','three-coloured','climbing','Brazilian','unusual','precious','tender','conservative'] },
  { id:93, emoji:'💛', title:'Clivia',            latin:'Clivia miniata',           description:'Clivia produces gorgeous clusters of deep orange, yellow, or red funnel-shaped flowers above strap-like, dark glossy foliage. A shade-loving South African native, it is an outstanding houseplant that blooms reliably in spring even in low-light rooms. In Japan, rare clivia cultivars with cream or yellow flowers fetch extraordinary sums at specialist auctions.',         tags:['shade-loving','houseplant','orange','reliable'], type:'Perennial', keywords:['clivia','orange','yellow','red','funnel','strap','shade','houseplant','South Africa','spring','glossy','Japan','rare','collector','auction'] },
  { id:94, emoji:'🌺', title:'Gaillardia',        latin:'Gaillardia x grandiflora', description:'Gaillardia, or blanket flower, blazes with vivid daisy-like flowers in hot combinations of red, orange, and yellow that suggest Native American blanket patterns — hence the name. Extraordinarily tough and long-blooming from late spring to autumn, they thrive in dry, poor soil in full sun. One of the most heat-tolerant and drought-resistant perennials available.',    tags:['bold','drought-tolerant','summer','Native American'], type:'Perennial', keywords:['gaillardia','blanket flower','red','orange','yellow','Native American','hot','drought','poor soil','tough','long-blooming','bold','summer','daisy','vivid'] },
  { id:95, emoji:'💙', title:'Plumbago',          latin:'Plumbago auriculata',      description:'Plumbago is a scrambling shrub from South Africa that produces clusters of sky-blue phlox-like flowers virtually year-round in frost-free climates. One of the bluest flowers in horticulture, it is beloved for wall training in Mediterranean gardens and grows rapidly to cover large areas. A white form exists, but it is the electric blue that makes it unforgettable.',     tags:['blue','Mediterranean','wall-climbing','tropical'], type:'Shrub', keywords:['plumbago','blue','sky-blue','South Africa','Mediterranean','wall','scrambling','year-round','tropical','phlox-like','electric blue','clusters','fast-growing','frost-free','vivid'] },
  { id:96, emoji:'🌸', title:'Pulsatilla',        latin:'Pulsatilla vulgaris',      description:'Pasque flower produces silky, nodding purple or white blooms in early spring on short stems covered in silver hairs, followed by extraordinary fluffy seed heads resembling mop tops that persist for months. It grows naturally on thin chalky grassland and is among Britain\'s rarest wildflowers. Its name refers to the Easter timing of its bloom.',                        tags:['early-spring','purple','rare','silky'],   type:'Perennial', keywords:['pulsatilla','pasque flower','purple','white','silky','nodding','hairy','chalky','Easter','rare','British','wildflower','seed head','fluffy','spring'] },
  { id:97, emoji:'🌺', title:'Meconopsis',        latin:'Meconopsis betonicifolia', description:'The Himalayan blue poppy is one of horticulture\'s most coveted and notoriously difficult plants — a true sky-blue colour almost uniquely among poppies. Growing at altitude in Himalayan meadows, it requires cool, moist conditions and is a reliable perennial only in Scotland and cool humid climates. Achieving its bloom is a gardener\'s greatest triumph.',             tags:['rare','blue','Himalayan','difficult'],    type:'Perennial', keywords:['meconopsis','Himalayan blue poppy','blue','rare','difficult','cool','moist','Scotland','altitude','trophy','precious','sky-blue','coveted','poppy','meadow'] },
  { id:98, emoji:'💛', title:'Rudbeckia',         latin:'Rudbeckia fulgida',        description:'Rudbeckia, or black-eyed Susan, is among the most reliable and cheerful perennials — producing an unceasing display of golden daisy flowers with dark chocolate-brown centres from midsummer to autumn frost. Named in honour of two Swedish professors, it tolerates drought, poor soil, and competition and self-seeds to naturalise in borders and meadow gardens.',             tags:['reliable','yellow','autumn','easy'],     type:'Perennial', keywords:['rudbeckia','black-eyed susan','yellow','golden','brown centre','summer','autumn','reliable','drought','easy','self-seed','meadow','naturalize','daisy','cheerful'] },
  { id:99, emoji:'🌸', title:'Pentas',            latin:'Pentas lanceolata',        description:'Pentas, or star cluster, produces flat-topped clusters of tiny star-shaped flowers in red, pink, lilac, and white. An essential butterfly and hummingbird plant in tropical gardens, it blooms continuously in warm climates. In colder regions it is grown as a summer annual in containers. Native to eastern Africa and Yemen, it is incredibly heat-tolerant.',             tags:['butterfly','hummingbird','tropical','continuous-blooming'], type:'Annual', keywords:['pentas','star cluster','red','pink','lilac','white','butterfly','hummingbird','tropical','African','continuous','heat-tolerant','container','annual','summer'] },
  { id:100,emoji:'🌺', title:'Tibouchina',        latin:'Tibouchina urvilleana',    description:'Tibouchina, or princess flower, produces spectacular velvety purple blooms the size of saucers, among the most intense and vivid purples in horticulture. A vigorous South American shrub, it blooms prolifically in warm climates and is irresistible when grown against white walls. The large, ribbed leaves are themselves beautiful, covered in soft hairs that give them a silvery sheen.', tags:['purple','dramatic','tropical','South American'], type:'Shrub', keywords:['tibouchina','princess flower','purple','velvety','large','spectacular','South America','intense','vivid','shrub','wall','warm','ribbed','silky','dramatic'] },

  // ── 101-120: Fragrance & Cutting ──
  { id:101,emoji:'🌸', title:'Stephanotis',       latin:'Stephanotis floribunda',   description:'Stephanotis, or Madagascar jasmine, produces waxy white star-shaped flowers with an intoxicatingly heavy, sweet fragrance that has made it an essential wedding flower for over a century. A climbing tropical plant, it is demanding to grow but rewards with extraordinary blooms. Bridal bouquets and boutonnieres frequently feature stephanotis for its classic beauty.',    tags:['wedding','fragrant','white','classic'],   type:'Climber',   keywords:['stephanotis','Madagascar jasmine','white','waxy','fragrant','wedding','bridal','tropical','climbing','sweet','classic','bouquet','boutonniere','star','intoxicating'] },
  { id:102,emoji:'💛', title:'Acacia',            latin:'Acacia baileyana',         description:'Wattle, or golden mimosa, is Australia\'s national floral emblem — masses of tiny golden yellow pompom flowers covering silvery-blue fernlike foliage in late winter and spring. Australia Day is informally called Wattle Day. The wood is dense and prized for crafts; the flowers and seeds have been used as food by Aboriginal Australians for thousands of years.',          tags:['Australian','national','yellow','winter'], type:'Tree', keywords:['acacia','wattle','yellow','golden','Australian','national emblem','pompom','blue-grey','feathery','winter','spring','Australia Day','Aboriginal','food','fragrant'] },
  { id:103,emoji:'🌸', title:'Mock Orange',       latin:'Philadelphus coronarius',  description:'Mock orange is a deciduous shrub that earns its name from the powerful orange-blossom fragrance of its pure white, four-petalled flowers, which carry on the air with extraordinary persistence in early summer. One of the most fragrant hardy garden plants, a single shrub can perfume an entire garden on a still June evening. It is easy to grow and tolerates shade.',     tags:['fragrant','white','easy','summer'],       type:'Shrub',     keywords:['mock orange','philadelphus','white','fragrant','orange blossom','scent','summer','hardy','easy','June','deciduous','four-petalled','shrub','shade','perfume'] },
  { id:104,emoji:'💜', title:'Buddleia',          latin:'Buddleja davidii',         description:'Buddleja, the butterfly bush, produces long arching plumes of tiny purple, white, or pink flowers with a honey-vanilla fragrance from midsummer to autumn. It is one of the most effective plants for attracting butterflies, earning it the butterfly bush name. Though considered invasive in some regions, its unmatched value to pollinators makes it a classic garden plant.',   tags:['butterfly','fragrant','summer','purple'], type:'Shrub',     keywords:['buddleia','butterfly bush','purple','pink','white','butterfly','fragrant','honey','vanilla','summer','autumn','nectar','pollinator','plume','classic'] },
  { id:105,emoji:'🌸', title:'Daphne',            latin:'Daphne odora',             description:'Daphne produces clusters of tiny, intensely fragrant pink and white flowers in late winter and early spring, when the garden is at its most barren. The scent — sweet, musky, and penetrating — is one of the most powerful in horticulture and can be detected from metres away. An enigmatic plant with a capricious nature, it can die suddenly even in ideal conditions.',   tags:['fragrant','winter','pink','capricious'],  type:'Shrub',     keywords:['daphne','pink','white','fragrant','winter','spring','intense','musky','powerful','enigmatic','difficult','cluster','early','capricious','evergreen'] },
  { id:106,emoji:'💛', title:'Forsythia',         latin:'Forsythia x intermedia',   description:'Forsythia is a beacon of spring hope — bare branches suddenly exploding into cascades of bright yellow four-petalled flowers in late winter before a single leaf appears. Fast-growing and tolerant of difficult conditions, it is among the most reliable spring-flowering shrubs. It flowers on old wood, so pruning should be done immediately after flowering finishes.',    tags:['spring','yellow','early','reliable'],     type:'Shrub',     keywords:['forsythia','yellow','spring','early','bare branches','cascade','reliable','fast-growing','hardy','winter','pruning','four-petalled','beacon','cheerful','deciduous'] },
  { id:107,emoji:'🌸', title:'Viburnum',          latin:'Viburnum x bodnantense',   description:'Winter viburnums produce clusters of intensely sweet pink flowers on bare stems through the coldest months, their fragrance extraordinary given the harsh conditions. Viburnum opulus, the guelder rose, follows with huge white lacecap flowers in spring, then translucent red berry clusters in autumn. Few shrubs offer such year-round ornamental value.',                tags:['winter','fragrant','pink','multi-season'], type:'Shrub', keywords:['viburnum','pink','white','winter','fragrant','sweet','clusters','berry','autumn','multi-season','hardy','deciduous','bare stems','guelder rose','reliable'] },
  { id:108,emoji:'🌺', title:'Statice',           latin:'Limonium sinuatum',        description:'Statice, or sea lavender, produces papery clusters of tiny flowers in rich purple, blue, white, pink, and yellow that dry naturally on the plant and retain their colour for years. One of the most useful everlasting flowers for dried arrangements, they add colour and texture to bouquets and wreaths. The dried flowers are a staple of rustic and Provençal-style floristry.',tags:['dried flower','everlasting','purple','florist'], type:'Annual', keywords:['statice','sea lavender','purple','blue','pink','papery','dried','everlasting','long-lasting','arrangement','wreath','rustic','Provençal','florist','texture'] },
  { id:109,emoji:'💛', title:'Hypericum',         latin:'Hypericum perforatum',     description:'Hypericum, or St. John\'s wort, produces cheerful star-shaped golden yellow flowers above translucent-spotted leaves that have been used medicinally for depression since antiquity. The berries of ornamental hypericums — in copper, red, white, and black — are enormously popular in autumn floristry, adding rich texture to harvest arrangements.',                    tags:['medicinal','berries','yellow','autumn'],  type:'Shrub',     keywords:['hypericum','St. John\'s wort','yellow','star','berries','copper','red','autumn','medicinal','depression','floristry','arrangement','harvest','texture','ornamental'] },
  { id:110,emoji:'🌸', title:'Gypsophila',        latin:'Gypsophila paniculata',    description:'Baby\'s breath is the quintessential filler flower — clouds of tiny white or pale pink blooms on branching stems that bring an airy, romantic softness to any arrangement. A staple of wedding floristry for over a century, it contrasts beautifully with bold flowers and dries easily. Its association with innocence and purity makes it the perfect complement to roses.',  tags:['filler','wedding','white','airy'],        type:'Perennial', keywords:['gypsophila','baby\'s breath','white','pink','tiny','airy','cloud','wedding','filler','romantic','innocence','purity','dried','arrangement','roses'] },
  { id:111,emoji:'💜', title:'Heliotrope',        latin:'Heliotropium arborescens', description:'Heliotrope, or cherry pie, produces dense clusters of tiny purple or white flowers with an extraordinarily sweet, almond-vanilla fragrance beloved by the Victorians. Named for its ability to turn towards the sun, it was the most fashionable summer bedding plant of the nineteenth century. Growing it today feels like communing with a Victorian garden.',               tags:['fragrant','Victorian','purple','nostalgic'], type:'Annual', keywords:['heliotrope','cherry pie','purple','fragrant','almond','vanilla','Victorian','bedding','sweet','nostalgic','sun-tracking','summer','classic','annual','cluster'] },
  { id:112,emoji:'🌸', title:'Dianthus',          latin:'Dianthus caryophyllus',    description:'Dianthus, including carnations, pinks, and sweet williams, are cottage garden classics with fringed, spice-scented flowers in every shade of pink, red, white, and bicolour. Their clove-like fragrance has been beloved since antiquity — the word carnation derives from the Latin for garland, as they were used to crown victors. They dry beautifully and last well in vases.', tags:['fragrant','cottage','classic','fringed'], type:'Perennial', keywords:['dianthus','carnation','pinks','sweet william','fringed','clove','fragrant','spice','pink','red','white','cottage','classic','ancient','garland'] },
  { id:113,emoji:'💛', title:'Lycoris',           latin:'Lycoris radiata',          description:'Lycoris, or resurrection lily, produces clusters of extraordinary spidery pink or golden flowers on bare leafless stems in late summer or autumn, arising suddenly after a dry period just as the leaves die. In Japan, red lycoris blooms in Buddhist cemeteries and is associated with death and the journey to the afterlife. Its dramatic appearance makes it unforgettable.',   tags:['unusual','Japanese','autumn','dramatic'],  type:'Bulb', keywords:['lycoris','resurrection lily','spider lily','pink','red','golden','bare stem','Japan','Buddhist','cemetery','death','afterlife','dramatic','autumn','unusual'] },
  { id:114,emoji:'🌸', title:'Oncidium',          latin:'Oncidium sphacelatum',     description:'Dancing lady orchids, or oncidiums, produce tall branching sprays of dozens of small yellow and brown blooms that tremble in the slightest breeze, resembling a cascade of dancing figures. One of the most floriferous orchids, they are easier to grow than many and reward with spectacular seasonal displays. Their sweet vanilla fragrance is an added pleasure.',      tags:['orchid','yellow','fragrant','cascading'], type:'Orchid', keywords:['oncidium','dancing lady','orchid','yellow','brown','spray','cascade','fragrant','vanilla','easy','floriferous','dancing','tropical','seasonal','branching'] },
  { id:115,emoji:'💜', title:'Echium',            latin:'Echium vulgare',           description:'Vipers bugloss is a native European wildflower with rough, bristly stems and intensely blue, bee-revered flowers. The garden form Echium pininana from the Canary Islands grows to four metres tall in mild climates, producing a majestic column of hundreds of blue-purple flowers beloved by bumblebees. One of the most dramatic hardy plants that can be grown in temperate gardens.',tags:['blue','wildlife','dramatic','wildflower'], type:'Biennial', keywords:['echium','vipers bugloss','blue','purple','bee','bristly','wild','Canary Islands','tall','dramatic','column','temperate','hardy','bumblebee','dramatic'] },
  { id:116,emoji:'🌸', title:'Pieris',            latin:'Pieris japonica',          description:'Pieris, or lily of the valley shrub, produces cascading strings of tiny white or pink urn-shaped flowers in early spring above glossy foliage. Its chief ornamental asset is its dramatic spring growth flush of brilliant red new shoots that gradually age to pink and then green, creating a three-colour effect. A beautiful evergreen shrub for acid soils.',                tags:['spring','white','evergreen','shrub'],     type:'Shrub',     keywords:['pieris','lily of the valley shrub','white','pink','red','new growth','spring','evergreen','acid soil','cascading','urn-shaped','ornamental','shrub','Japanese','glossy'] },
  { id:117,emoji:'💛', title:'Potentilla',        latin:'Potentilla fruticosa',      description:'Shrubby potentilla is one of the most reliably long-blooming shrubs available, producing small buttercup-like flowers in white, yellow, orange, pink, and red continuously from late spring to the first frosts of autumn. Completely hardy and tolerant of poor, dry soil, it needs no deadheading and asks only for a sunny spot in return for months of cheerful colour.',     tags:['long-blooming','easy','yellow','hardy'],  type:'Shrub',     keywords:['potentilla','buttercup','yellow','white','orange','pink','long-blooming','easy','hardy','dry','poor soil','sunny','shrub','reliable','months'] },
  { id:118,emoji:'🌸', title:'Bergenia',          latin:'Bergenia cordifolia',      description:'Bergenia, or elephant ears, produces thick clusters of bright magenta, pink, or white flowers on sturdy red stems in earliest spring, often poking through snow. Their large, leathery, rounded leaves turn burgundy and bronze in winter, providing year-round interest. Hardy, shade-tolerant, and slug-resistant, they are reliable groundcover plants for difficult spots.',    tags:['early-spring','ground-cover','pink','hardy'], type:'Perennial', keywords:['bergenia','elephant ears','pink','magenta','white','early spring','snow','leathery','leaf','burgundy','winter','ground cover','shade','hardy','slug-resistant'] },
  { id:119,emoji:'💜', title:'Baptisia',          latin:'Baptisia australis',       description:'False indigo is a spectacular American prairie native producing upright spikes of rich indigo-blue pea-like flowers in late spring above blue-green clover-like foliage. Incredibly long-lived and drought-tolerant once established, individual plants can live for decades. The inflated seed pods that follow are ornamental and rattle dramatically in the autumn wind.',    tags:['blue','prairie','native','long-lived'],   type:'Perennial', keywords:['baptisia','false indigo','blue','indigo','pea-flower','prairie','American','native','drought','long-lived','decades','seed pod','spring','clover-like','spectacular'] },
  { id:120,emoji:'🌸', title:'Weigela',           latin:'Weigela florida',          description:'Weigela is a reliable, unfussy deciduous shrub that smothers itself in funnel-shaped flowers in pink, red, or white in late spring and early summer. New cultivars offer striking purple or bronze foliage that provides colour through the growing season. A classic cottage garden shrub, it is beloved by long-tongued bumblebees and is easy to establish in any garden.',   tags:['reliable','pink','cottage','bee-friendly'], type:'Shrub', keywords:['weigela','pink','red','white','funnel','deciduous','late spring','cottage','bumblebee','easy','purple foliage','bronze','reliable','shrub','classic'] },

  // ── 121-140: Orchids & Rare ──
  { id:121,emoji:'🌸', title:'Phalaenopsis Orchid',latin:'Phalaenopsis amabilis',  description:'Moth orchids are the world\'s most popular houseplant, producing arching sprays of large, elegant flowers in white, pink, lilac, yellow, and elaborate spotted forms that last for months. Native to tropical Asian rainforests, they thrive in indirect light and require little water. Named because their flowers resemble moths in flight, they represent luxury, beauty, and refinement.',tags:['orchid','houseplant','elegant','long-lasting'], type:'Orchid', keywords:['phalaenopsis','moth orchid','white','pink','orchid','houseplant','long-lasting','tropical','Asian','luxury','elegant','arching','spray','months','refinement'] },
  { id:122,emoji:'💜', title:'Dendrobium Orchid', latin:'Dendrobium nobile',        description:'Dendrobium orchids produce clusters of waxy, fragrant flowers along their tall cane-like pseudobulbs in purple, white, yellow, and pink. Popular in traditional medicine across Asia and used in gourmet cuisine, they bloom spectacularly once or twice a year. The canes can be used to make shi hu, a precious Chinese herbal tonic believed to strengthen health.',              tags:['orchid','fragrant','Asian','medicinal'],  type:'Orchid',    keywords:['dendrobium','orchid','purple','white','yellow','fragrant','Asian','cane','pseudobulb','medicinal','Chinese herbal','shi hu','gourmet','waxy','clusters'] },
  { id:123,emoji:'🌸', title:'Cymbidium Orchid',  latin:'Cymbidium',               description:'Cymbidium orchids produce long arching sprays of large, elegant blooms in green, yellow, pink, white, and burgundy, often with contrasting lip colours. A symbol of Confucian virtue and refinement in Chinese culture, they have been cultivated for over two thousand years. Cooler-growing than most orchids, they can be grown outdoors in mild climates and are popular for corsages.',tags:['orchid','long-lasting','Chinese','elegant'], type:'Orchid', keywords:['cymbidium','orchid','green','yellow','pink','burgundy','Chinese','Confucian','two thousand years','arching','elegant','corsage','cool-growing','spray','classical'] },
  { id:124,emoji:'💛', title:'Cattleya Orchid',   latin:'Cattleya labiata',        description:'Cattleya orchids are the quintessential corsage orchid — large, frilly, intensely fragrant blooms in pink, lavender, white, and yellow with a dramatically ruffled lip. Considered the queen of orchids, they demand specific care but reward with some of the most extravagant and beautiful flowers in the plant kingdom. Used extensively in orchid hybridisation for over 150 years.',tags:['orchid','fragrant','queen','dramatic'],   type:'Orchid',    keywords:['cattleya','orchid','queen','pink','lavender','white','yellow','frilly','corsage','fragrant','hybridisation','extravagant','dramatic','ruffled','beautiful'] },
  { id:125,emoji:'🌸', title:'Vanda Orchid',      latin:'Vanda coerulea',          description:'Vanda orchids produce large, flat-faced flowers in the rarest and most precious blue in the orchid world, as well as pink, orange, and yellow. Unusually grown with bare, air-breathing roots, they hang in baskets requiring high humidity and bright light. The blue vanda is Thailand\'s most prized ornamental plant and was a key parent in creating blue orchid hybrids.',  tags:['orchid','blue','rare','tropical'],        type:'Orchid',    keywords:['vanda','orchid','blue','pink','orange','rare','air-roots','Thailand','tropical','humidity','hanging','basket','precious','flat-faced','prized'] },
  { id:126,emoji:'💜', title:'Zygopetalum Orchid',latin:'Zygopetalum mackaii',      description:'Zygopetalum orchids produce extraordinary spidery flowers with wavy green and dark chocolate-brown petals and a bright blue-violet lip marked with purple veins, possessing a strong and lovely scent described as hyacinth-like with fruity notes. One of the most strongly perfumed orchids, they are increasingly popular with florists for their extraordinary colours.',    tags:['orchid','fragrant','unusual','bicoloured'], type:'Orchid', keywords:['zygopetalum','orchid','green','brown','blue','purple','fragrant','hyacinth','fruity','scented','spidery','florist','unusual','bicoloured','dramatic'] },
  { id:127,emoji:'🌸', title:'Masdevallia Orchid',latin:'Masdevallia coccinea',     description:'Masdevallia orchids from Andean cloud forests produce fascinating triangle-shaped flowers in vivid scarlet, orange, yellow, and white with tails extending from each sepal tip. They thrive in cool, foggy conditions that mimic their mountain habitat, making them suitable for cool growing rooms. Their unusual geometry and saturated colours make them extraordinary collector plants.',tags:['orchid','Andean','unusual','cool-growing'], type:'Orchid', keywords:['masdevallia','orchid','scarlet','orange','yellow','triangle','Andean','cloud forest','cool','fog','mountain','collector','unusual','geometry','tails'] },
  { id:128,emoji:'💛', title:'Epidendrum Orchid', latin:'Epidendrum ibaguense',     description:'Reed-stem epidendrums produce rounded clusters of tiny bright orange, red, yellow, or pink flowers at the tips of tall reed-like canes year-round in warm climates. Among the easiest orchids to grow outdoors in frost-free areas, they multiply into large colonies. Their vivid neon colouring and continuous blooming make them popular in tropical and subtropical gardens.',  tags:['orchid','easy','continuous','vivid'],     type:'Orchid',    keywords:['epidendrum','orchid','orange','red','yellow','reed','cane','easy','continuous','warm','tropical','colony','neon','vivid','year-round'] },
  { id:129,emoji:'🌸', title:'Miltoniopsis',      latin:'Miltoniopsis roezlii',     description:'Pansy orchids produce large, flat, velvet-textured flowers with wide-open faces resembling giant pansies in white, pink, red, and yellow with dramatic contrasting markings. Their sweet rose-like fragrance is notable among orchids. Cool-growing plants from cloud forests of Central and South America, they produce multiple flowers per stem and have a long flowering period.',tags:['orchid','fragrant','pansy-like','velvet'], type:'Orchid', keywords:['miltoniopsis','pansy orchid','white','pink','red','yellow','velvet','fragrant','rose-like','cloud forest','pansy-like','flat face','dramatic','markings','cool-growing'] },
  { id:130,emoji:'💜', title:'Pleione Orchid',    latin:'Pleione formosana',        description:'Pleione orchids are dwarf ground orchids from Himalayan mountainsides that produce single large lavender-pink flowers with a darker frilled lip in spring from tiny pseudobulbs the size of hazelnuts. Fully hardy in sheltered spots, they are among the most accessible orchids for outdoor cultivation in cool temperate gardens, creating a magical spring display.',         tags:['orchid','hardy','spring','small'],        type:'Orchid',    keywords:['pleione','orchid','pink','lavender','hardy','Himalayan','dwarf','spring','pseudobulb','frilled','lip','temperate','outdoor','accessible','magical'] },

  // ── 131-150: Final Collection ──
  { id:131,emoji:'🌸', title:'Lonicera',          latin:'Lonicera periclymenum',    description:'Honeysuckle is the quintessential cottage climbing plant, its tubular cream and pink flowers releasing the sweetest, most evocative scent on warm summer evenings. Native to European hedgerows and woodlands, its flowers feed long-tongued bumblebees while its red berries sustain birds in autumn. Few perfumes are as instantly nostalgic as honeysuckle on a still summer night.',tags:['fragrant','climbing','cottage','wildlife'], type:'Climber', keywords:['honeysuckle','lonicera','fragrant','tubular','cream','pink','summer','evening','bee','bird','berry','cottage','climbing','nostalgic','sweet'] },
  { id:132,emoji:'💛', title:'Tropaeolum',        latin:'Tropaeolum majus',         description:'Nasturtiums are endlessly cheerful, vigorous annuals with round lily-pad leaves and trumpet-shaped flowers in all shades of orange, red, yellow, and cream. Both flowers and leaves are edible and peppery-tasting, excellent in salads. They require no fertiliser — over-feeding produces leaves at the expense of flowers. From dry, poor soil they produce their best, brightest show.',tags:['edible','easy','orange','cottage'],       type:'Annual',    keywords:['nasturtium','tropaeolum','orange','yellow','red','edible','peppery','leaves','easy','poor soil','annual','climbing','cottage','trumpet','round leaves'] },
  { id:133,emoji:'🌸', title:'Deutzia',           latin:'Deutzia gracilis',         description:'Deutzia is an elegant deciduous shrub smothered in small pure white or pale pink star-shaped flowers in late spring. Incredibly graceful and floriferous, it combines beautifully with other late-spring flowering shrubs like weigela and lilac. Largely untroubled by pests or diseases, it asks very little from the gardener while giving generously of its spring display.',    tags:['white','spring','elegant','easy'],        type:'Shrub',     keywords:['deutzia','white','pink','star','spring','elegant','deciduous','floriferous','easy','graceful','shrub','untroubled','pest-free','generous','flowering'] },
  { id:134,emoji:'💜', title:'Tradescantia',      latin:'Tradescantia ohiensis',    description:'Spiderwort produces clusters of three-petalled flowers in rich violet, purple, blue, or pink at the tips of fleshy stems over blue-green strap-like foliage. Each flower lasts only a single day but new buds open continuously for months. The individual stamens are covered in tiny coloured hairs that were famously used by scientists to study the effects of radiation.',tags:['long-blooming','purple','native','unusual'], type:'Perennial', keywords:['tradescantia','spiderwort','purple','blue','violet','pink','three-petalled','one-day','continuous','radiation','stamen','hairs','science','native','American'] },
  { id:135,emoji:'🌸', title:'Silene',            latin:'Silene schafta',           description:'Silene, or catchfly, produces profuse bright magenta-pink flowers on low mats of foliage from late summer into autumn, precisely when much of the garden is fading. The sticky stems that give it its catchfly name trap insects, though it is not carnivorous. Completely hardy and easy to grow, it is an invaluable nectar source for late-season butterflies and bees.',       tags:['late-season','magenta','hardy','butterfly'], type:'Perennial', keywords:['silene','catchfly','pink','magenta','late season','autumn','mat-forming','sticky','butterfly','bee','easy','hardy','nectar','low-growing','ground cover'] },
  { id:136,emoji:'💛', title:'Kerria',            latin:'Kerria japonica',          description:'Kerria produces double or single bright yellow buttercup-like flowers on arching, bright green stems in spring. The double-flowered form, pleniflora, is a traditional cottage garden plant grown for at least 500 years. Its cheerful yellow and the fresh green of its winter stems provide valuable winter interest. It tolerates shade and spreads gently to form attractive thickets.',tags:['yellow','spring','shade-tolerant','traditional'], type:'Shrub', keywords:['kerria','yellow','buttercup','double','spring','arching','green stems','shade','cottage','traditional','historic','500 years','thicket','easy','Japanese'] },
  { id:137,emoji:'🌸', title:'Symphytum',         latin:'Symphytum officinale',     description:'Comfrey produces nodding clusters of tubular flowers in cream, pink, purple, and blue on large, rough-hairy plants. A deeply rooted perennial, it mines nutrients from deep in the soil and its leaves decompose rapidly to make exceptional plant food — comfrey "tea" is a highly valued organic liquid fertiliser. Its leaves were historically used to heal broken bones, earning it the name knitbone.',tags:['medicinal','wildlife','fertiliser','wildflower'], type:'Perennial', keywords:['comfrey','symphytum','purple','blue','cream','medicinal','knitbone','fertiliser','wildflower','bee','bumblebee','rough','large','robust','organic'] },
  { id:138,emoji:'💜', title:'Polemonium',        latin:'Polemonium caeruleum',     description:'Jacob\'s ladder produces elegant spikes of pure blue, white, or lavender cup-shaped flowers above distinctive ladder-like pinnate foliage. A cottage garden classic since Elizabethan times, it self-seeds gently and blooms freely in spring and early summer. The golden-leaved form "Brise d\'Anjou" with its cream-edged leaves is equally beautiful even before the flowers appear.',tags:['blue','cottage','Elizabethan','spring'],   type:'Perennial', keywords:['polemonium','Jacob\'s ladder','blue','white','lavender','ladder-like','pinnate','foliage','Elizabethan','cottage','self-seed','spring','elegant','cup-shaped','classic'] },
  { id:139,emoji:'🌸', title:'Primrose',          latin:'Primula vulgaris',         description:'The primrose is one of Britain\'s most beloved wildflowers and one of the very first to bloom in early spring, its pale lemon-yellow flowers with the characteristic darker yellow eye emerging from woodland floors and hedgebanks from February. Collecting wild primroses was once so prevalent it became illegal. Garden polyanthus are their highly bred, colourful descendants.',tags:['wildflower','spring','early','yellow'],   type:'Perennial', keywords:['primrose','pale yellow','spring','wildflower','British','woodland','hedgebank','early','February','polyanthus','classic','beloved','eye','illegal collecting','simple'] },
  { id:140,emoji:'💛', title:'Crocuses',          latin:'Crocus vernus',            description:'Crocuses are the jewel-bright harbingers of spring, pushing through snow or frozen soil in purple, gold, white, and striped varieties. They naturalise easily in lawns, their cheerful faces closing at night and on cloudy days. The prized spice saffron is derived from the dried red stigmas of Crocus sativus, requiring over 150,000 flowers to produce a single kilogram.',tags:['spring','bulb','early','naturalising'],   type:'Corm',      keywords:['crocus','purple','gold','white','spring','snow','naturalise','lawn','saffron','spice','early','jewel','corm','striped','cheerful'] },
  { id:141,emoji:'🌸', title:'Erysimum',          latin:'Erysimum cheiri',          description:'Wallflowers are old-fashioned cottage garden favourites with intensely fragrant four-petalled flowers in orange, yellow, red, deep purple, and cream. Biennial plants, they survive winter to bloom gloriously in spring. Planted in autumn alongside tulip bulbs, they create classic cottage combinations. The name wallflower comes from their habit of self-seeding in old stone walls.',tags:['fragrant','spring','cottage','biennial'],  type:'Biennial', keywords:['wallflower','erysimum','fragrant','orange','yellow','red','purple','biennial','spring','cottage','stone wall','self-seed','classic','combination','tulip'] },
  { id:142,emoji:'💛', title:'Inula',             latin:'Inula hookeri',            description:'Inula produces narrow-rayed golden yellow daisy flowers of extraordinary fineness — the petals so thin and numerous they create a frothy, almost hair-like golden halo. A cheerful, robust perennial for moist, sunny borders, it blooms in late summer when yellow is valuable in the garden. It self-seeds gently and is excellent in naturalistic and prairie-style planting.',tags:['yellow','summer','naturalistic','robust'],  type:'Perennial', keywords:['inula','golden','yellow','daisy','fine','frothy','narrow-rayed','halo','late summer','moist','sunny','naturalistic','self-seed','prairie','robust'] },
  { id:143,emoji:'🌸', title:'Tradescantia',      latin:'Tradescantia x andersoniana',description:'Garden spiderworts produce three-petalled flowers with contrasting stamens in purple, blue, pink, white, and bicoloured forms. Each flower lasts only a day but the plant produces hundreds over many weeks. They grow in clumps of strap-like foliage and are easy, reliable perennials that look wonderful beside ornamental grasses in naturalistic planting schemes.',        tags:['easy','purple','long-blooming','naturalistic'], type:'Perennial', keywords:['tradescantia','spiderwort','purple','blue','pink','three-petalled','stamen','clump','strap','grasses','naturalistic','easy','reliable','summer','day-flower'] },
  { id:144,emoji:'💜', title:'Scilla',            latin:'Scilla siberica',          description:'Siberian squill produces small, intensely blue nodding bells in very early spring, naturalising freely in grass and under deciduous trees to create sheets of pure blue that carpet the ground between snowdrops and tulips. Among the most intense blues available in early-season bulbs, they require no attention once planted and increase freely year after year.',            tags:['blue','spring','bulb','naturalising'],    type:'Bulb',      keywords:['scilla','siberian squill','blue','bells','early spring','naturalise','grass','woodland','intense','sheets','carpet','bulb','under trees','increase','free'] },
  { id:145,emoji:'🌸', title:'Abutilon',          latin:'Abutilon megapotamicum',   description:'Abutilon, or flowering maple, produces pendant Chinese lantern-like flowers in red calyces cradling a yellow skirt over extremely long seasons. A scrambling wall shrub in mild climates, it flowers almost continuously from spring to autumn and provides nectar for bees and hummingbirds. Its lobed maple-like leaves and elegant flowers give it an exotic but refined charm.',tags:['unusual','wall-shrub','long-season','tropical'], type:'Shrub', keywords:['abutilon','flowering maple','red','yellow','pendant','lantern','exotic','wall','hummingbird','bee','long season','tropical','spring','autumn','elegant'] },
  { id:146,emoji:'💛', title:'Trollius',          latin:'Trollius europaeus',       description:'Globeflowers are refined wildflowers of damp alpine meadows producing perfectly rounded, globe-shaped flowers in pale to deep golden yellow in late spring. They resemble buttercups of extraordinary restraint and beauty, each bloom a perfect sphere. They grow in boggy soils and pondside areas, naturalising in damp meadow gardens where they create a golden carpet.',    tags:['alpine','yellow','bog','elegant'],        type:'Perennial', keywords:['trollius','globeflower','yellow','golden','globe','sphere','alpine','meadow','damp','bog','elegant','buttercup','late spring','pondside','restrained'] },
  { id:147,emoji:'🌸', title:'Linum',             latin:'Linum perenne',            description:'Perennial flax produces the most exquisite sky-blue flowers on thread-fine wiry stems that dance in the breeze, each bloom lasting only a single day but replaced by new ones continuously through summer. The unmatched purity of its blue and its feathery delicacy make it one of the most beautiful of all wildflower species. Annual flax produces the valuable linen fibre.',tags:['blue','delicate','wildflower','sky-blue'], type:'Perennial', keywords:['linum','flax','blue','sky-blue','wiry','delicate','thread-fine','wildflower','dancing','summer','linen','fibre','continuous','one-day','pure'] },
  { id:148,emoji:'💜', title:'Lobelia',           latin:'Lobelia erinus',           description:'Trailing and upright lobelias produce masses of tiny two-lipped flowers in rich cobalt blue, purple, red, and white that provide essential colour in hanging baskets and container displays through summer. Perennial cardinal flower lobelias produce spikes of vivid red that attract hummingbirds. The intense blue trailing forms are one of the most popular summer bedding plants.',tags:['container','blue','hanging basket','summer'], type:'Annual', keywords:['lobelia','blue','cobalt','purple','red','two-lipped','hanging basket','container','bedding','summer','hummingbird','cardinal flower','trailing','intense','tiny'] },
  { id:149,emoji:'🌸', title:'Schizanthus',       latin:'Schizanthus pinnatus',     description:'Poor man\'s orchid produces masses of butterfly-shaped flowers of extraordinary intricacy — each one veined and marked in pink, red, purple, yellow, and white — above delicate fern-like foliage. A Chilean native, it is grown as an annual and produces a remarkable display that genuinely resembles a collection of miniature orchids. Perfect for cool greenhouses and sheltered spots.',tags:['orchid-like','unusual','intricate','colorful'], type:'Annual', keywords:['schizanthus','poor man\'s orchid','butterfly flower','pink','red','purple','yellow','intricate','orchid-like','Chilean','fern','veined','annual','greenhouse','cool'] },
  { id:150,emoji:'💛', title:'Geum',              latin:'Geum chiloense',           description:'Geums produce cheerful bowl-shaped flowers in vivid orange, red, yellow, and peachy-apricot on wiry stems above rosettes of coarsely textured leaves. Incredibly easy and long-blooming from late spring to early autumn, they are invaluable gap-fillers in the cottage or mixed border. The double-flowered Lady Stratheden and Mrs. J. Bradshaw varieties are classic cottage plants.',tags:['easy','orange','long-blooming','cottage'],  type:'Perennial', keywords:['geum','orange','red','yellow','apricot','bowl-shaped','wiry','easy','long-blooming','spring','autumn','cottage','double','classic','gap-filler'] }
];
